import React from "react";

interface SecludeLogoProps {
  className?: string;
  style?: React.CSSProperties;
  /** "full" = stacked icon+text (tall), "horizontal" = icon+text side by side (wide), "mark" = icon only */
  variant?: "full" | "horizontal" | "mark";
  /** "color" = original brand greens (light backgrounds), "light" = white (dark backgrounds) */
  tone?: "color" | "light";
}

// Official Seclude Hotels logo — high-resolution source, cropped and separated into
// stacked / horizontal / icon-only variants, embedded as base64 so it never depends on
// seclude.in (which blocks hotlinking with a 403 Forbidden).
const LOGO = {
  full: {
    color: "data:image/png;base64,",
    light: "data:image/png;base64,",
  },
  horizontal: {
    color: "data:image/png;base64,",
    light: "data:image/png;base64,",
  },
  mark: {
    color: "data:image/png;base64,",
    light: "data:image/png;base64,",
  },
};

export default function SecludeLogo({ className, style, variant = "full", tone = "color" }: SecludeLogoProps) {
  return (
    <img
      src={LOGO[variant][tone]}
      alt="Seclude Hotels"
      className={className}
      style={{ objectFit: "contain", ...style }}
    />
  );
}
